const firebaseConfig={apiKey:"AIzaSyA3BL6qvC6OkcLql_CBBTOCWXSuTuUuunU",authDomain:"gp-blog-admin.firebaseapp.com",projectId:"gp-blog-admin",storageBucket:"gp-blog-admin.firebasestorage.app",messagingSenderId:"454725222443",appId:"1:454725222443:web:e27f38252a4013824e2a6e",measurementId:"G-YB94M7KK2T"};firebase.apps&&firebase.apps.length||firebase.initializeApp(firebaseConfig);const blogDb=firebase.firestore();let _publishedPostsCache=null;async function fetchPublishedPosts(){if(_publishedPostsCache)return _publishedPostsCache;const e=await blogDb.collection("blogPosts").where("published","==",!0).get(),a=[];return e.forEach(e=>a.push({id:e.id,...e.data()})),a.sort((e,a)=>(a.createdAt?a.createdAt.toMillis():0)-(e.createdAt?e.createdAt.toMillis():0)),_publishedPostsCache=a,a}async function fetchPostBySlug(e){return(await fetchPublishedPosts()).find(a=>a.slug===e)||null}let _dailyCache=null;async function fetchPublishedDailyUpdates(e){if(!_dailyCache){const e=await blogDb.collection("dailyUpdates").where("published","==",!0).get(),a=[];e.forEach(e=>a.push({id:e.id,...e.data()})),a.sort((e,a)=>(a.createdAt?a.createdAt.toMillis():0)-(e.createdAt?e.createdAt.toMillis():0)),_dailyCache=a}return"number"==typeof e?_dailyCache.slice(0,e):_dailyCache}function blogFormatDate(e){return e?e.toDate().toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}):""}function blogReadTime(e){const a=(e.content||"").replace(/<[^>]*>/g," "),t=a.trim().length?a.trim().split(/\s+/).filter(Boolean).length:0;return Math.max(1,Math.round(t/200))}function blogCoverImage(e){return e.imageUrl||e.imageUrls&&e.imageUrls[0]||"assets/gp_logo.png"}function blogEscapeHtml(e){const a=document.createElement("div");return a.textContent=null==e?"":String(e),a.innerHTML}const BLOG_PUBLISHER_LOGO="assets/publisher-mark.webp",BLOG_PUBLISHER_NAME="Glyphic Palette";function blogCardHTML(e){const a=blogCoverImage(e),t=blogCategoryLabel(e)||e.tags&&e.tags[0]||"Journal";return`\n    <a class="blog-card" href="blog-post.html?slug=${encodeURIComponent(e.slug)}">\n      <div class="blog-card-img">\n        <div class="blog-card-img-bg" style="background-image:url('${a}')" aria-hidden="true"></div>\n        <img src="${a}" alt="" loading="lazy">\n      </div>\n      <div class="blog-card-body">\n        <div class="blog-card-tagrow">\n          <span class="blog-card-tag">${blogEscapeHtml(t)}</span>\n          ${e.featured?'<span class="blog-card-featured">Featured</span>':""}\n        </div>\n        <h3 class="blog-card-title">${blogEscapeHtml(e.title)}</h3>\n        <p class="blog-card-excerpt">${blogEscapeHtml(e.excerpt||"")}</p>\n        <div class="blog-card-meta">\n          <span class="blog-card-publisher"><img class="blog-card-publisher-logo" src="${BLOG_PUBLISHER_LOGO}" alt="" loading="lazy">Glyphic Palette</span>\n          <span class="blog-card-dot">·</span>\n          <span>${blogFormatDate(e.createdAt)}</span>\n          <span class="blog-card-dot">·</span>\n          <span>${blogReadTime(e)} min read</span>\n        </div>\n      </div>\n    </a>`}
const BLOG_CATEGORIES={
"marketing":{label:"Marketing",blurb:"Social media, ads, SEO and the numbers behind getting seen.",icon:'<svg viewBox="0 0 24 24"><path d="M3 11v2a1 1 0 0 0 1 1h2l5 4V6L6 10H4a1 1 0 0 0-1 1z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg>'},
"content-creation":{label:"Content Creation",blurb:"Ideas, scripts, shoots and edits that earn real attention.",icon:'<svg viewBox="0 0 24 24"><path d="M4 20l4-1 11-11a2.1 2.1 0 0 0-3-3L5 16l-1 4z"/><path d="M14 7l3 3"/></svg>'},
"business-growth":{label:"Business Growth",blurb:"Brand, pricing and systems that help a business scale.",icon:'<svg viewBox="0 0 24 24"><path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/></svg>'}
};
const BLOG_CATEGORY_KEYS=Object.keys(BLOG_CATEGORIES);
function blogCategoryOf(p){return p&&BLOG_CATEGORIES[p.category]?p.category:null}
function blogCategoryLabel(p){const k=blogCategoryOf(p);return k?BLOG_CATEGORIES[k].label:""}

function renderPostSidebar(posts,current){
  const root=document.getElementById("blog-sidebar");if(!root)return;
  const esc=blogEscapeHtml,abs=u=>/^(https?:|\/|data:)/.test(u)?u:"/"+u;
  const byCat={};BLOG_CATEGORY_KEYS.forEach(k=>byCat[k]=posts.filter(p=>blogCategoryOf(p)===k&&p.slug));
  let active=blogCategoryOf(current)||BLOG_CATEGORY_KEYS.find(k=>byCat[k].length)||BLOG_CATEGORY_KEYS[0];

  root.innerHTML=`<div class="bsb-backdrop" data-bsb-close></div>
<div class="bsb-panel" role="dialog" aria-label="Browse more posts">
  <span class="bsb-handle"></span>
  <div class="bsb-head">
    <div><p class="bsb-eyebrow">Keep reading</p><h3 class="bsb-title">Browse the journal</h3></div>
    <button type="button" class="bsb-close" data-bsb-close aria-label="Close"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
  </div>
  <div class="bsb-tabs" role="tablist">${BLOG_CATEGORY_KEYS.map(k=>`<button type="button" role="tab" class="bsb-tab" data-cat="${k}">${BLOG_CATEGORIES[k].label}<small>${byCat[k].length}</small></button>`).join("")}</div>
  <p class="bsb-blurb"></p>
  <ul class="bsb-list" role="tabpanel"></ul>
  <a class="bsb-foot" href="#"></a>
</div>`;

  const tabs=root.querySelectorAll(".bsb-tab"),list=root.querySelector(".bsb-list"),blurb=root.querySelector(".bsb-blurb"),foot=root.querySelector(".bsb-foot");

  function paint(swap){
    tabs.forEach(t=>{const on=t.dataset.cat===active;t.classList.toggle("is-active",on);t.setAttribute("aria-selected",on)});
    const c=BLOG_CATEGORIES[active],items=byCat[active];
    blurb.textContent=c.blurb;
    foot.href="/blog.html#"+active;
    foot.innerHTML="All "+esc(c.label)+" posts <span aria-hidden=\"true\">\u2192</span>";
    list.innerHTML=items.length?items.map(p=>{
      const cur=current&&p.slug===current.slug;
      const inner=`<img class="bsb-thumb" src="${esc(abs(blogCoverImage(p)))}" alt="" loading="lazy"><span class="bsb-info">${cur?'<span class="bsb-now">Reading now</span>':""}<span class="bsb-item-title">${esc(p.title)}</span><span class="bsb-item-meta">${blogFormatDate(p.createdAt)} \u00b7 ${blogReadTime(p)} min read</span></span>`;
      return `<li class="bsb-item${cur?" is-current":""}">${cur?`<div class="bsb-link" aria-current="page">${inner}</div>`:`<a class="bsb-link" href="/blog-post.html?slug=${encodeURIComponent(p.slug)}">${inner}</a>`}</li>`;
    }).join(""):`<li class="bsb-empty">Fresh ${esc(c.label)} posts are on the way.</li>`;
    if(swap){list.classList.remove("is-swap");void list.offsetWidth;list.classList.add("is-swap");list.scrollTop=0}
    else{const cur=list.querySelector(".is-current");if(cur)list.scrollTop=Math.max(0,cur.getBoundingClientRect().top-list.getBoundingClientRect().top+list.scrollTop-12)}
  }
  tabs.forEach(t=>t.addEventListener("click",()=>{active=t.dataset.cat;paint(true)}));
  paint(false);

  let fab=document.querySelector(".bsb-fab");
  if(!fab){
    fab=document.createElement("button");fab.type="button";fab.className="bsb-fab";fab.setAttribute("aria-label","Browse more posts");
    fab.innerHTML='<svg viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h10"/></svg><span>Browse posts</span>';
    document.body.appendChild(fab);
  }
  const open=()=>{root.classList.add("is-open");document.documentElement.classList.add("bsb-lock");fab.classList.add("is-hidden")};
  const close=()=>{root.classList.remove("is-open");document.documentElement.classList.remove("bsb-lock");fab.classList.remove("is-hidden")};
  fab.addEventListener("click",open);
  root.addEventListener("click",e=>{if(e.target.closest("[data-bsb-close]"))close()});
  document.addEventListener("keydown",e=>{if(e.key==="Escape")close()});
  window.matchMedia("(min-width:1100px)").addEventListener("change",close);
}